            return re.sub(email_pattern, REPLACE_NONE, obj)
        elif isinstance(obj, dict):
            return {k: replace_emails(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [replace_emails(item) for item in obj]
        else:
            return obj

    data = replace_emails(data)

    def flatten(obj):
        values = []
        if isinstance(obj, dict):
            for v in obj.values():
                values.extend(flatten(v))
        elif isinstance(obj, list):
            for item in obj:
                values.extend(flatten(item))
        else:
            values.append(obj)
